 private FrameLayout screenRoot(){FrameLayout frame=new FrameLayout(this);frame.setBackground(gradient(Color.rgb(19,29,41),Color.rgb(9,14,20),0));ImageView watermark=new ImageView(this);Bitmap original=BitmapFactory.decodeResource(getResources(),R.drawable.sene_logo);Bitmap smoothLogo=Bitmap.createScaledBitmap(original,1024,640,true);watermark.setImageBitmap(smoothLogo);if(original!=smoothLogo)original.recycle();watermark.setScaleType(ImageView.ScaleType.FIT_CENTER);watermark.setAlpha(0.035f);FrameLayout.LayoutParams wm=new FrameLayout.LayoutParams(dp(320),dp(200),Gravity.CENTER);watermark.setAlpha(0.035f);frame.addView(watermark,wm);return frame;}
